html:
{%- macro words(number) -%}
{{ frappe.utils.in_words(number) | replace(",", "") | replace(" and ", " ") | title }}
{%- endmacro -%}

{%- macro amount_in_words(amount, unit, fraction_unit) -%}
{%- set amount = frappe.utils.flt(amount, 2) -%}
{%- set whole = frappe.utils.cint(amount) -%}
{%- set fraction = frappe.utils.cint(frappe.utils.flt((amount - whole) * 100, 0)) -%}
{%- if whole or not fraction -%}{{ words(whole) }} {{ unit }}{%- endif -%}
{%- if fraction -%}{{ " and " if whole }}{{ words(fraction) }} {{ fraction_unit }}{%- endif %} Only
{%- endmacro -%}

{%- macro money(amount) -%}{{ currency }} {{ frappe.utils.fmt_money(amount, 2) }}{%- endmacro -%}

{#- Payer bank: the Company Bank Account picked on the entry, else the one linked to the Paid From account -#}
{%- set bank_fields = ["account_name", "bank", "bank_account_no", "iban"] -%}
{%- set payer_bank = (doc.bank_account and frappe.db.get_value("Bank Account", doc.bank_account, bank_fields, as_dict=True))
	or frappe.db.get_value("Bank Account", {"account": doc.paid_from, "is_company_account": 1, "disabled": 0}, bank_fields, as_dict=True) -%}
{%- if payer_bank -%}
	{%- set bank_name = payer_bank.bank -%}
	{%- set bank_short = payer_bank.bank -%}
	{%- set account_name = payer_bank.account_name -%}
	{%- set account_no = payer_bank.bank_account_no -%}
	{%- set iban = payer_bank.iban -%}
	{%- set swift = frappe.db.get_value("Bank", payer_bank.bank, "swift_number") -%}
{%- elif "first abu dhabi" in (doc.paid_from or "") | lower -%}
	{%- set bank_name = "First Abu Dhabi Bank" -%}
	{%- set bank_short = "FAB" -%}
	{%- set account_name = "BIN OMEIR MOTORS COMPANY LLCOPC" -%}
	{%- set account_no = "1001327077173001" -%}
	{%- set iban = "AE850351001327077173001" -%}
	{%- set swift = "NBADAEAA" -%}
{%- else -%}
	{%- set bank_name = doc.paid_from -%}
	{%- set bank_short = "" -%}
	{%- set account_name = doc.company -%}
	{%- set account_no = "" -%}
	{%- set iban = "" -%}
	{%- set swift = "" -%}
{%- endif -%}

{%- set currency = doc.paid_from_account_currency or doc.paid_to_account_currency or "AED" -%}
{%- if currency == "AED" -%}
	{%- set currency_unit, fraction_unit = "UAE Dirhams", "Fils" -%}
{%- else -%}
	{%- set currency_unit, fraction_unit = currency, frappe.db.get_value("Currency", currency, "fraction") or "" -%}
{%- endif -%}

{%- if doc.docstatus == 0 -%}{%- set payment_status = "Pending Approval" -%}
{%- elif doc.docstatus == 1 -%}{%- set payment_status = "Paid" -%}
{%- else -%}{%- set payment_status = "Cancelled" -%}{%- endif -%}

{%- set date_fields = {
	"Purchase Invoice": ["bill_date", "posting_date"],
	"Journal Entry": ["bill_date", "posting_date"],
	"Purchase Order": ["transaction_date", "transaction_date"],
} -%}

{%- set totals = {"outstanding": 0, "paid": 0} -%}
{%- set rows = [] -%}
{%- for ref in doc.references -%}
	{#- On submit ERPNext refreshes outstanding_amount to the balance after this payment -#}
	{%- set outstanding = ref.outstanding_amount + (ref.allocated_amount if doc.docstatus == 1 else 0) -%}
	{%- set fields = date_fields.get(ref.reference_doctype) -%}
	{%- set invoice_date = None -%}
	{%- if fields -%}
		{%- set dates = frappe.db.get_value(ref.reference_doctype, ref.reference_name, fields) -%}
		{%- set invoice_date = dates and (dates[0] or dates[1]) -%}
	{%- endif -%}
	{%- set _ = rows.append({
		"bill_no": ref.bill_no or ref.reference_name,
		"reference_name": ref.reference_name if ref.bill_no else "",
		"invoice_date": invoice_date or ref.due_date,
		"bill_amount": ref.total_amount,
		"outstanding": outstanding,
		"paid": ref.allocated_amount,
	}) -%}
	{%- set _ = totals.update({"outstanding": totals.outstanding + outstanding, "paid": totals.paid + ref.allocated_amount}) -%}
{%- endfor -%}
{%- set balance = totals.outstanding - totals.paid -%}

<style>
	.prv { font-family: Arial, Helvetica, sans-serif; color: #1f2937; font-size: 11px; }
	.prv table { width: 100%; border-collapse: collapse; }
	.prv td, .prv th { vertical-align: top; }
	.prv .navy { color: #0f4c81; }

	.prv-head td { vertical-align: middle; }
	.prv-logo { height: 52px; }
	.prv-title {
		display: inline-block; background: #0f4c81; color: #fff; font-weight: bold;
		font-size: 15px; letter-spacing: .5px; padding: 6px 12px; border-radius: 3px;
	}
	.prv-ref { margin-top: 8px; font-weight: bold; font-size: 12px; }
	.prv-date { color: #4b5563; font-size: 12px; }
	.prv-rule { border-top: 3px solid #0f4c81; margin: 14px 0 20px; }

	.prv-bank { background: #eef5fd; border: 1px solid #dbe7f5; border-left: 5px solid #0f4c81; border-radius: 3px; padding: 10px 14px 12px; }
	.prv-bank-title { font-weight: bold; color: #0f4c81; font-size: 11.5px; letter-spacing: .3px; padding-bottom: 6px; border-bottom: 1px solid #d3e1f1; margin-bottom: 8px; }
	.prv-label { color: #6b7280; font-weight: bold; font-size: 9.5px; text-transform: uppercase; }
	.prv-bank-value { color: #0f4c81; font-weight: bold; font-size: 11.5px; }

	.prv-info { margin-top: 18px; border: 1px solid #d1d5db; }
	.prv-info > tbody > tr > td { padding: 8px 12px; width: 50%; }
	.prv-info > tbody > tr > td + td { border-left: 1px solid #d1d5db; }
	.prv-kv td { padding: 1px 0; font-size: 11.5px; }
	.prv-kv td.k { color: #4b5563; font-weight: bold; width: 46%; padding-right: 6px; }
	.prv-kv td.v { font-weight: bold; color: #111827; }

	.prv-items { margin-top: 18px; }
	.prv-items thead { display: table-header-group; }
	.prv-items tr { page-break-inside: avoid; }
	.prv-items th { background: #0f4c81; color: #fff; font-weight: bold; font-size: 11.5px; padding: 8px 10px; text-align: left; border: 1px solid #0f4c81; }
	.prv-items td { padding: 8px 10px; font-size: 11.5px; border: 1px solid #d1d5db; }
	.prv-items .r { text-align: right; }
	.prv-items .c { text-align: center; }
	.prv-sub { color: #9ca3af; font-size: 9.5px; }

	.prv-totals { width: 58% !important; margin: 18px 0 0 auto; page-break-inside: avoid; }
	.prv-totals td { border: 1px solid #d1d5db; padding: 7px 12px; font-size: 11.5px; }
	.prv-totals td.k { font-weight: bold; color: #111827; }
	.prv-totals td.v { text-align: right; width: 38%; }
	.prv-totals tr.hl td { background: #eef5fd; }
	.prv-totals tr.hl td.k { color: #0f4c81; }
	.prv-totals tr.hl td.v { font-weight: bold; color: #0f4c81; }

	.prv-words { margin-top: 18px; background: #f8fafc; border: 1px solid #e5e7eb; border-left: 5px solid #0f4c81; border-radius: 3px; padding: 8px 14px; page-break-inside: avoid; }
	.prv-words.grey { border-left-color: #64748b; }
	.prv-words .w { font-weight: bold; font-size: 13px; color: #0f4c81; margin-top: 2px; }
	.prv-words.grey .w { color: #1f2937; font-size: 12px; }

	.prv-auth-title { margin-top: 22px; font-weight: bold; font-size: 13px; color: #0f4c81; padding-bottom: 6px; border-bottom: 2px solid #0f4c81; }
	.prv-auth { margin-top: 16px; page-break-inside: avoid; }
	.prv-auth > tbody > tr > td { width: 48%; }
	.prv-auth > tbody > tr > td.gap { width: 4%; }
	.prv-sign { border: 1px solid #d1d5db; border-radius: 4px; padding: 12px 14px 14px; }
	.prv-sign.approve { border: 2px solid #0f4c81; }
	.prv-sign-title { font-weight: bold; font-size: 12px; color: #374151; padding-bottom: 6px; border-bottom: 1px solid #e5e7eb; }
	.prv-sign.approve .prv-sign-title { color: #0f4c81; }
	.prv-sign-space { height: 38px; border-bottom: 1px dashed #9ca3af; }
	.prv-sign-row td { padding-top: 8px; font-size: 11px; color: #4b5563; }
	.prv-sign.approve .prv-sign-row td { color: #0f4c81; font-weight: bold; }

</style>

<div class="prv">
	<table class="prv-head">
		<tr>
			<td style="width: 55%;"><img class="prv-logo" src="data:image/png;base64," alt="Bin Omeir Motors Company"></td>
			<td style="text-align: right;">
				<span class="prv-title">PAYMENT REQUEST VOUCHER</span>
				<div class="prv-ref">Ref: {{ doc.name }}</div>
				<div class="prv-date">Date: {{ frappe.utils.formatdate(doc.posting_date, "dd-MM-yyyy") }}</div>
			</td>
		</tr>
	</table>
	<div class="prv-rule"></div>

	<div class="prv-bank">
		<div class="prv-bank-title">PAYER BANK ACCOUNT DETAILS{% if bank_name %} ({{ bank_name | upper }}){% endif %}</div>
		<table>
			<tr>
				<td class="prv-label">Account Name</td>
				<td class="prv-label">Account Number</td>
				<td class="prv-label">IBAN Number</td>
				<td class="prv-label" style="text-align: right;">SWIFT Code</td>
			</tr>
			<tr>
				<td class="prv-bank-value">{{ account_name or "" }}</td>
				<td class="prv-bank-value">{{ account_no or "" }}</td>
				<td class="prv-bank-value">{{ iban or "" }}</td>
				<td class="prv-bank-value" style="text-align: right;">{{ swift or "" }}</td>
			</tr>
		</table>
	</div>

	<table class="prv-info">
		<tr>
			<td>
				<table class="prv-kv">
					<tr><td class="k">Payee / Supplier Name:</td><td class="v">{{ doc.party_name or doc.party }}</td></tr>
					<tr><td class="k">Voucher Reference No:</td><td class="v">{{ doc.name }}</td></tr>
					<tr><td class="k">Payment Mode:</td><td class="v">{{ doc.mode_of_payment or "" }}{% if bank_short %} ({{ bank_short }}){% endif %}</td></tr>
				</table>
			</td>
			<td>
				<table class="prv-kv">
					<tr><td class="k">Total Invoices Included:</td><td class="v">{{ rows | length }} Invoice{{ "s" if rows | length != 1 }}</td></tr>
					<tr><td class="k">Voucher Date:</td><td class="v">{{ frappe.utils.formatdate(doc.posting_date, "dd-MM-yyyy") }}</td></tr>
					<tr><td class="k">Payment Status:</td><td class="v">{{ payment_status }}</td></tr>
				</table>
			</td>
		</tr>
	</table>

	<table class="prv-items">
		<thead>
			<tr>
				<th class="c" style="width: 5%;">#</th>
				<th style="width: 19%;">Invoice No</th>
				<th style="width: 16%;">Invoice Date</th>
				<th class="r" style="width: 20%;">Bill Amount</th>
				<th class="r" style="width: 20%;">Outstanding</th>
				<th class="r" style="width: 20%;">Payment Amount</th>
			</tr>
		</thead>
		<tbody>
			{%- for row in rows %}
			<tr>
				<td class="c">{{ loop.index }}</td>
				<td>{{ row.bill_no }}{% if row.reference_name %}<div class="prv-sub">{{ row.reference_name }}</div>{% endif %}</td>
				<td>{{ frappe.utils.formatdate(row.invoice_date, "dd-MM-yyyy") if row.invoice_date else "" }}</td>
				<td class="r">{{ money(row.bill_amount) }}</td>
				<td class="r">{{ money(row.outstanding) }}</td>
				<td class="r">{{ money(row.paid) }}</td>
			</tr>
			{%- endfor %}
		</tbody>
	</table>

	<table class="prv-totals">
		<tr><td class="k">Total Previous Outstanding:</td><td class="v">{{ money(totals.outstanding) }}</td></tr>
		<tr class="hl"><td class="k">Total Requested Payment:</td><td class="v">{{ money(totals.paid) }}</td></tr>
		<tr class="hl"><td class="k">Total Balance Remaining:</td><td class="v">{{ money(balance) }}</td></tr>
	</table>

	<div class="prv-words">
		<div class="prv-label">Total Requested Payment Amount in Words</div>
		<div class="w">{{ amount_in_words(totals.paid, currency_unit, fraction_unit) }}</div>
	</div>
	<div class="prv-words grey">
		<div class="prv-label">Remaining Balance Amount in Words</div>
		<div class="w">{{ amount_in_words(balance, currency_unit, fraction_unit) }}</div>
	</div>

	<div class="prv-auth-title">AUTHORIZATION &amp; APPROVALS</div>
	<table class="prv-auth">
		<tr>
			<td>
				<div class="prv-sign">
					<div class="prv-sign-title">PREPARED BY</div>
					<div class="prv-sign-space"></div>
					<table class="prv-sign-row"><tr>
						<td>Signature:<br>______________________</td>
						<td style="width: 34%;">Date:<br>____/____/{{ frappe.utils.getdate(doc.posting_date).year }}</td>
					</tr></table>
				</div>
			</td>
			<td class="gap"></td>
			<td>
				<div class="prv-sign approve">
					<div class="prv-sign-title">APPROVED BY</div>
					<div class="prv-sign-space"></div>
					<table class="prv-sign-row"><tr>
						<td>Signature:<br>______________________</td>
						<td style="width: 34%;">Date:<br>____/____/{{ frappe.utils.getdate(doc.posting_date).year }}</td>
					</tr></table>
				</div>
			</td>
		</tr>
	</table>
</div>

<div id="footer-html" class="visible-pdf">
	<table style="width: 100%; border-top: 1px solid #e5e7eb; font-family: Arial, Helvetica, sans-serif; font-size: 9px; color: #6b7280;">
		<tr>
			<td style="padding-top: 6px;">Bin Omeir Motors Company LLCOPC &mdash; Accounts Payable Payment Request</td>
			<td style="padding-top: 6px; text-align: right;">{{ doc.name }}</td>
		</tr>
	</table>
</div>
